<?php
namespace Zarincode\Theme\Core;
defined('ABSPATH') || exit;
/** Bounded custom links. SVG is sanitized markup, never a global upload permission. */
final class Social_Manager {
    public static function boot():void {
        add_action('admin_menu',static function(){add_submenu_page(null,'شبکه‌های اجتماعی دلخواه','شبکه‌های اجتماعی','manage_options','zarincode-socials',[self::class,'page']);});
        add_action('admin_enqueue_scripts',static function($hook){if(strpos($hook,'zarincode-socials')===false && Admin_Hub::selected()!=='socials')return;wp_enqueue_media();wp_enqueue_style('zc-social-admin-icons',get_template_directory_uri().'/assets/fontawesome/css/all.min.css',[],ZARINCODE_VERSION);wp_enqueue_script('zc-social-manager',get_template_directory_uri().'/assets/js/social-manager.js',['jquery'],ZARINCODE_VERSION,true);});
    }
    public static function svg($raw):string {return class_exists('Zarincode\\Runtime260\\Content\\Social_Profile_Store')?\Zarincode\Runtime260\Content\Social_Profile_Store::svg($raw):'';}
    public static function template($raw):string {return class_exists('Zarincode\\Runtime260\\Content\\Social_Profile_Store')?\Zarincode\Runtime260\Content\Social_Profile_Store::template($raw):'';}
    public static function sanitize($rows):array {return class_exists('Zarincode\\Runtime260\\Content\\Social_Profile_Store')?\Zarincode\Runtime260\Content\Social_Profile_Store::sanitize($rows):[];}
    public static function rows():array {if(class_exists('Zarincode\\Runtime260\\Features\\Manager')&&!\Zarincode\Runtime260\Features\Manager::enabled('social_profiles'))return [];return class_exists('Zarincode\\Runtime260\\Content\\Social_Profile_Store')?\Zarincode\Runtime260\Content\Social_Profile_Store::rows():[];}
    public static function url($raw):string {return class_exists('Zarincode\\Runtime260\\Content\\Social_Profile_Store')?\Zarincode\Runtime260\Content\Social_Profile_Store::url($raw):'';}
    public static function icon(array $r):string {
        if($r['type']==='svg'&&$r['svg'])return $r['svg'];if($r['type']==='image'&&$r['image'])return wp_get_attachment_image($r['image'],[24,24],false,['alt'=>'','aria-hidden'=>'true','loading'=>'lazy']);return '<i aria-hidden="true" class="'.esc_attr($r['font']).'"></i>';
    }
    public static function row(array $row,$index):void {
        $name='zc_socials['.$index.']';echo '<fieldset class="zc-social-admin-row" style="padding:18px;border:1px solid #ccd0d4;border-radius:10px;margin:15px 0;background:white"><input type="hidden" name="'.esc_attr($name).'[id]" value="'.esc_attr($row['id']??wp_generate_uuid4()).'"><p><label><input type="checkbox" name="'.esc_attr($name).'[enabled]" value="1" '.checked($row['enabled']??true,true,false).'> نمایش این شبکه</label></p>';
        foreach(['name'=>'نام شبکه','url'=>'پیوند حساب یا پشتیبانی','share_template'=>'الگوی اختیاری اشتراک: https://example.com/share?url={url}&text={title}'] as $key=>$label)echo '<p><label>'.esc_html($label).'<input class="widefat" name="'.esc_attr($name).'['.$key.']" value="'.esc_attr($row[$key]??'').'" '.($key!=='name'?'dir="ltr"':'').'></label></p>';
        echo '<p><label>نوع آیکون <select name="'.esc_attr($name).'[type]">';foreach(['font'=>'فونت آیکون','svg'=>'فایل یا کد SVG ایمن','image'=>'تصویر کتابخانه رسانه'] as $v=>$t)echo '<option value="'.$v.'" '.selected($row['type']??'font',$v,false).'>'.$t.'</option>';echo '</select></label></p><p><label>کلاس Font Awesome <input dir="ltr" list="zc-social-fonts" name="'.esc_attr($name).'[font]" value="'.esc_attr($row['font']??'fa-solid fa-link').'"></label></p><p><label>کد SVG <textarea class="widefat" rows="3" dir="ltr" name="'.esc_attr($name).'[svg]">'.esc_textarea($row['svg']??'').'</textarea></label><input class="zc-social-svg-file" type="file" accept=".svg,image/svg+xml" aria-label="انتخاب فایل SVG"></p><p><input type="hidden" class="zc-social-image-id" name="'.esc_attr($name).'[image]" value="'.esc_attr($row['image']??0).'"><button type="button" class="button zc-social-image">انتخاب PNG / تصویر</button> <span class="zc-social-image-label">'.esc_html($row['image']??'').'</span></p><button type="button" class="button zc-social-up">↑ جابه‌جایی بالا</button> <button type="button" class="button zc-social-remove">حذف شبکه</button></fieldset>';
    }
    public static function page():void {if(!current_user_can('manage_options'))return;if(class_exists('Zarincode\\Runtime260\\Features\\Manager')&&!\Zarincode\Runtime260\Features\Manager::enabled('social_profiles')){echo '<div class="notice notice-info"><p>'.esc_html__('Custom social profile services are disabled. Existing data is retained.','zarincode').'</p></div>';return;}
        if(did_action('zarincode_social_profiles_saved'))echo '<div class="notice notice-success" role="status"><p>شبکه‌ها ذخیره شدند.</p></div>';
        echo '<div class="wrap"><h1>شبکه‌های اجتماعی دلخواه</h1><p>واتساپ، تلگرام و شبکه‌های شناخته‌شده در تنظیمات قالب باقی‌اند. اینجا شبکه‌های تکمیلی را با آیکون اختصاصی اضافه کنید. الگوی اشتراک فقط باید از مستندات رسمی مقصد گرفته شود؛ خالی یعنی فقط حساب ارتباطی. SVG بارگذاری عمومی نمی‌شود و فقط شکل‌های ایمن نگه داشته می‌شوند.</p><form method="post">';wp_nonce_field('zc_socials');echo '<input type="hidden" name="zc_socials" value=""><div id="zc-social-admin-list">';foreach(get_option('zarincode_custom_socials',[]) as $i=>$row)if(is_array($row))self::row($row,$i);echo '</div><template id="zc-social-row-template">';self::row([],'__INDEX__');echo '</template><datalist id="zc-social-fonts">';foreach(['fa-brands fa-whatsapp','fa-brands fa-telegram','fa-brands fa-instagram','fa-brands fa-youtube','fa-brands fa-discord','fa-brands fa-pinterest','fa-solid fa-link','fa-solid fa-comments'] as $f)echo '<option value="'.esc_attr($f).'">';echo '</datalist><button type="button" id="zc-social-add" class="button">افزودن شبکه</button>';submit_button('ذخیره شبکه‌ها','primary','zc_social_save');echo '</form></div>';
    }
}
